// ─── File: PartitionedCounter.java ───
package com.bank.leaderboard;

import java.util.*;

// Each item hashes to ONE partition = one authoritative owner.
public class PartitionedCounter {
    private final int partitions;
    private final List<Map<String,Long>> owners = new ArrayList<>();

    public PartitionedCounter(int partitions) {
        this.partitions = partitions;
        for (int i = 0; i < partitions; i++) owners.add(new HashMap<>());
    }
    private int ownerOf(String itemId) { return Math.abs(itemId.hashCode()) % partitions; }

    public void count(String itemId, int weight) {
        owners.get(ownerOf(itemId)).merge(itemId, (long) weight, Long::sum);
    }

    // each owner produces its local top-K (complete counts, since one owner per item)
    public List<List<Map.Entry<String,Long>>> localTopK(int k) {
        List<List<Map.Entry<String,Long>>> result = new ArrayList<>();
        for (Map<String,Long> owner : owners) {
            PriorityQueue<Map.Entry<String,Long>> heap =
                new PriorityQueue<>(Map.Entry.comparingByValue());
            for (var e : owner.entrySet()) { heap.offer(e); if (heap.size() > k) heap.poll(); }
            List<Map.Entry<String,Long>> local = new ArrayList<>(heap);
            local.sort(Map.Entry.<String,Long>comparingByValue().reversed());
            result.add(local);
        }
        return result;
    }
}
