// ─── File: RollingWindow.java ───
package com.bank.leaderboard;

public class RollingWindow {
    private final long windowMs;
    private final long allowedLatenessMs;
    public RollingWindow(long windowMs, long allowedLatenessMs) {
        this.windowMs = windowMs; this.allowedLatenessMs = allowedLatenessMs;
    }
    // admit if the event is within the window and not later than allowed lateness
    public boolean admit(EngagementEvent e, long watermark) {
        long age = watermark - e.eventTime();
        boolean withinWindow = age <= windowMs;
        boolean notTooLate = age <= windowMs + allowedLatenessMs;
        return withinWindow && notTooLate;
    }
}
```

